package com.adesa.attendance.attendance;

import java.time.Instant;
import java.time.LocalDate;
import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.PrePersist;
import jakarta.persistence.PreUpdate;
import jakarta.persistence.Table;

/**
 * One attendance record per employee per workday.
 *
 * <p>The timestamps are absolute instants generated by the server. The workday
 * ({@link #attendanceDate}) is the employee's local calendar day in the
 * configured attendance timezone.
 *
 * <p>Employees never mutate their own timestamps through the API: the record is
 * only created by a sign-in and only closed by a sign-out, both performed by
 * the backend.
 */
@Entity
@Table(name = "attendance_records")
public class AttendanceRecord {

    @Id
    @Column(name = "id", nullable = false)
    private UUID id;

    @Column(name = "employee_id", nullable = false)
    private UUID employeeId;

    /** Local workday this record belongs to. */
    @Column(name = "attendance_date", nullable = false)
    private LocalDate attendanceDate;

    @Column(name = "sign_in_at", nullable = false)
    private Instant signInAt;

    @Column(name = "sign_out_at")
    private Instant signOutAt;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    protected AttendanceRecord() {
        // for JPA
    }

    public AttendanceRecord(UUID employeeId, LocalDate attendanceDate, Instant signInAt) {
        this.id = UUID.randomUUID();
        this.employeeId = employeeId;
        this.attendanceDate = attendanceDate;
        this.signInAt = signInAt;
    }

    @PrePersist
    void onCreate() {
        Instant now = Instant.now();
        createdAt = now;
        updatedAt = now;
    }

    @PreUpdate
    void onUpdate() {
        updatedAt = Instant.now();
    }

    /** Closes the workday. Called only by the sign-out operation. */
    public void signOut(Instant signOutAt) {
        this.signOutAt = signOutAt;
    }

    /**
     * Applies an authorized manual correction.
     *
     * <p>Only HR and administrators may call this, always with a mandatory
     * reason that is stored in {@code attendance_corrections} and in the audit
     * log. The previous values are never lost: they are captured by the caller
     * before this method runs.
     */
    public void applyCorrection(Instant correctedSignInAt, Instant correctedSignOutAt) {
        this.signInAt = correctedSignInAt;
        this.signOutAt = correctedSignOutAt;
    }

    public UUID getId() {
        return id;
    }

    public UUID getEmployeeId() {
        return employeeId;
    }

    public LocalDate getAttendanceDate() {
        return attendanceDate;
    }

    public Instant getSignInAt() {
        return signInAt;
    }

    public Instant getSignOutAt() {
        return signOutAt;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }
}
